        Pc::Mat{8,8} = [39124.3578 -371191.186 -347608.37 -436369.708 23527.1151 -100008.86 -79104.6319 -55803.2088; -371191.186 12098489.8 12330895.5 18780604.9 -625934.976 3442082.83 2907746.39 2253634.26; -347608.37 12330895.5 13581014.1 18794598.4 -600728.321 3544330.32 3018673.34 2287018.12; -436369.708 18780604.9 18794598.4 42887969.5 -797542.281 5841925.77 5296221.87 4749684.63; 23527.1151 -625934.976 -600728.321 -797542.281 36950.8702 -170387.679 -137549.715 -99867.1198; -100008.86 3442082.83 3544330.32 5841925.77 -170387.679 1001019.84 859979.642 687936.115; -79104.6319 2907746.39 3018673.34 5296221.87 -137549.715 859979.642 749558.207 614821.6; -55803.2088 2253634.26 2287018.12 4749684.63 -99867.1198 687936.115 614821.6 534610.789], [description = "LQR cost-to-go matrix of the catch rule"]
        t_on::Real = 1.0, [unit = "s", description = "Start of the swing-up"]
        t_s::Real = 4.0, [unit = "s", min = 0, description = "Swing-up duration of the trajectory"]
        dt_tab::Real = 0.01, [unit = "s", min = 0, description = "Row spacing of the table"]
        catch_tol::Real = 1.0, [min = 0, description = "Catch threshold of the cost-to-go x^T Pc x"]
        umax::Real = 15.0, [unit = "V", min = 0, description = "Amplifier voltage limit"]
    end
    @variables latched::Real = 0.0, [description = "1 once the balance controller has taken over"]
    @discrete Ts = 1e-3 begin
        tau = tm - t_on
        s = clamp(tau / dt_tab, 0.0, NT - 1.0) + 1.0
        c1 = 0.0
        c2 = 0.0
        c3 = 0.0
        c4 = 0.0
        c5 = 0.0
        c6 = 0.0
        c7 = 0.0
        c8 = 0.0
        c9 = 0.0
        c10 = 0.0
        c11 = 0.0
        c12 = 0.0
        c13 = 0.0
        c14 = 0.0
        c15 = 0.0
        c16 = 0.0
        c17 = 0.0
        for k in 1:NT
            wk = max(0.0, 1.0 - abs(s - k))
            c1 = c1 + wk * Tab[k, 1]
            c2 = c2 + wk * Tab[k, 2]
            c3 = c3 + wk * Tab[k, 3]
            c4 = c4 + wk * Tab[k, 4]
            c5 = c5 + wk * Tab[k, 5]
            c6 = c6 + wk * Tab[k, 6]
            c7 = c7 + wk * Tab[k, 7]
            c8 = c8 + wk * Tab[k, 8]
            c9 = c9 + wk * Tab[k, 9]
            c10 = c10 + wk * Tab[k, 10]
            c11 = c11 + wk * Tab[k, 11]
            c12 = c12 + wk * Tab[k, 12]
            c13 = c13 + wk * Tab[k, 13]
            c14 = c14 + wk * Tab[k, 14]
            c15 = c15 + wk * Tab[k, 15]
            c16 = c16 + wk * Tab[k, 16]
            c17 = c17 + wk * Tab[k, 17]
        end
        utv = c9 - (c10 * (q1 - c1) + c11 * (q2 - c2) + c12 * (q3 - c3) + c13 * (q4 - c4) + c14 * (w1 - c5) + c15 * (w2 - c6) + c16 * (w3 - c7) + c17 * (w4 - c8))
        ulq = -(Klqr[1] * q1 + Klqr[2] * q2 + Klqr[3] * q3 + Klqr[4] * q4 + Klqr[5] * w1 + Klqr[6] * w2 + Klqr[7] * w3 + Klqr[8] * w4)
        en = Pc[1, 1] * q1 * q1 + 2.0 * Pc[1, 2] * q1 * q2 + 2.0 * Pc[1, 3] * q1 * q3 + 2.0 * Pc[1, 4] * q1 * q4 + 2.0 * Pc[1, 5] * q1 * w1 + 2.0 * Pc[1, 6] * q1 * w2 + 2.0 * Pc[1, 7] * q1 * w3 + 2.0 * Pc[1, 8] * q1 * w4 + Pc[2, 2] * q2 * q2 + 2.0 * Pc[2, 3] * q2 * q3 + 2.0 * Pc[2, 4] * q2 * q4 + 2.0 * Pc[2, 5] * q2 * w1 + 2.0 * Pc[2, 6] * q2 * w2 + 2.0 * Pc[2, 7] * q2 * w3 + 2.0 * Pc[2, 8] * q2 * w4 + Pc[3, 3] * q3 * q3 + 2.0 * Pc[3, 4] * q3 * q4 + 2.0 * Pc[3, 5] * q3 * w1 + 2.0 * Pc[3, 6] * q3 * w2 + 2.0 * Pc[3, 7] * q3 * w3 + 2.0 * Pc[3, 8] * q3 * w4 + Pc[4, 4] * q4 * q4 + 2.0 * Pc[4, 5] * q4 * w1 + 2.0 * Pc[4, 6] * q4 * w2 + 2.0 * Pc[4, 7] * q4 * w3 + 2.0 * Pc[4, 8] * q4 * w4 + Pc[5, 5] * w1 * w1 + 2.0 * Pc[5, 6] * w1 * w2 + 2.0 * Pc[5, 7] * w1 * w3 + 2.0 * Pc[5, 8] * w1 * w4 + Pc[6, 6] * w2 * w2 + 2.0 * Pc[6, 7] * w2 * w3 + 2.0 * Pc[6, 8] * w2 * w4 + Pc[7, 7] * w3 * w3 + 2.0 * Pc[7, 8] * w3 * w4 + Pc[8, 8] * w4 * w4
        lat = ifelse(latched > 0.5 || (tau >= t_s && en < catch_tol), 1.0, 0.0)
        latched = lat
        u = clamp(ifelse(tm < t_on, 0.0, ifelse(lat > 0.5, ulq, utv)), -umax, umax)
        phase = ifelse(tm < t_on, 0.0, ifelse(lat > 0.5, 2.0, 1.0))
        vcost = en
    end
end
